figures={"title":"17世紀後半〜18世紀初めの将軍と側近","nodes":[{"id":"ietsuna","name":"徳川家綱","role":"4代将軍","x":20,"y":8},{"id":"hoshina","name":"保科正之","role":"叔父・会津藩主","x":70,"y":8},{"id":"tsunayoshi","name":"徳川綱吉","role":"5代将軍","x":20,"y":36},{"id":"yanagisawa","name":"柳沢吉保","role":"側用人","x":70,"y":28},{"id":"ogiwara","name":"荻原重秀","role":"勘定吟味役","x":70,"y":46},{"id":"ienobu","name":"徳川家宣","role":"6代将軍","x":20,"y":64},{"id":"hakuseki","name":"新井白石","role":"朱子学者","x":70,"y":64},{"id":"manabe","name":"間部詮房","role":"側用人","x":70,"y":82},{"id":"ietsugu","name":"徳川家継","role":"7代将軍（3歳）","x":20,"y":88}],"links":[{"from":"hoshina","to":"ietsuna","label":"補佐","kind":"mentor"},{"from":"yanagisawa","to":"tsunayoshi","label":"側用人","kind":"ally"},{"from":"ogiwara","to":"tsunayoshi","label":"改鋳を進言","kind":"ally"},{"from":"hakuseki","to":"ienobu","label":"正徳の政治","kind":"mentor"},{"from":"manabe","to":"ienobu","label":"側用人","kind":"ally"},{"from":"ienobu","to":"ietsugu","label":"子","kind":"mentor"}],
"dramas":[{"tag":"ミニドラマ","title":"なぜ、刀より礼儀なのか？","cast":"徳川綱吉 × 柳沢吉保 × かぶき者","lines":[{"who":"かぶき者","say":"おれたちは戦国の世なら一番槍で出世できたんだ。派手な格好で暴れて何が悪い。いつか戦がおきれば、また腕で成り上がってやるよ。"},{"who":"徳川綱吉","say":"その考えはもう通らぬ。武家諸法度の第1条も書きかえた。「文武弓馬の道」ではなく「文武忠孝を励し、礼儀を正すべき事」だ（天和令）。主君に忠、親に孝、そして礼儀。これが今の武士の道だ。"},{"who":"柳沢吉保","say":"上様は湯島聖堂を建て、林信篤どのを大学頭にされました。生き物を殺すなとのお触れ（生類憐みの令）も、喪に服す日数の決まり（服忌令）も出ております。人を斬って出世する時代は、もう終わったのです。"},{"who":"かぶき者","say":"犬を大事にしろ、喪に服せ、礼儀を正せ……。戦がなくなると、武士は役人になっちまうのか。"}]}]}
cloze=[{"title":"文治政治への転換","text":"1651年に3代将軍が死去すると、子の[[徳川家綱]]が11歳で将軍となり、叔父で会津藩主の[[保科正之]]らがこれを補佐した。同年、兵学者による[[慶安の変]]がおこると、幕府は大名の[[末期養子]]の禁止を緩和して牢人の増加を防いだ。1663年には代がわりの武家諸法度とあわせて[[殉死]]を禁じ、家臣は主人個人ではなく主人の家に仕えるべきことを明らかにした。諸藩でも儒者を顧問とする藩政の刷新がはかられ、岡山藩主の池田光政は郷校の[[閑谷学校]]を設けて[[熊沢蕃山]]を重く用い、水戸藩主の徳川光圀は江戸に[[彰考館]]を設けて歴史書の編纂を始めた。5代将軍綱吉は、大老の暗殺後に側用人の[[柳沢吉保]]を重用した。1683年の武家諸法度（[[天和令]]）では、第1条が「文武忠孝を励し、礼儀を正すべき事」に改められた。綱吉は孔子をまつる[[湯島聖堂]]を建て、[[林信篤]]を大学頭に任じた。また20年あまりにわたって[[生類憐みの令]]を出し、近親者の死に際して喪に服す日数を定めた[[服忌令]]も出した。財政の悪化に対しては、勘定吟味役[[荻原重秀]]の進言で質を落とした小判を発行したが、物価の騰貴をまねいた。6代将軍家宣のもとで朱子学者の[[新井白石]]と側用人の[[間部詮房]]が政治を主導し、幕府が費用を献じて[[閑院宮家]]を創設させた。白石は1715年に[[海舶互市新例]]を出して長崎貿易の額を制限した。"},
{"title":"農業と諸産業の発達","text":"17世紀後半以降、農具が改良され、田の深耕には[[備中鍬]]、脱穀には扱箸にかわって[[千歯扱]]、穀粒の選別には[[千石簁]]や[[唐箕]]、揚水には[[踏車]]が用いられた。耕地の開発で刈敷が不足すると、干鰯・〆粕・油粕などの[[金肥]]が商品作物の生産地で広まった。17世紀末には[[宮崎安貞]]が日本最初の体系的な農書である『[[農業全書]]』を著した。田畑の面積は江戸時代初めの164万町歩から、18世紀初めには[[297万町歩]]に拡大した。各地には特産品が生まれ、出羽村山地方の[[紅花]]、阿波の[[藍玉]]、備後の藺草などが知られた。塩業では潮の干満を利用して海水を引きこむ[[入浜塩田]]が瀬戸内海沿岸などで発達した。高級絹織物は京都の[[西陣]]で独占的に織られていたが、18世紀中頃には上野の[[桐生]]などでも生産されるようになった。醸造業では伏見や灘の酒、関東の[[野田]]や銚子の醤油が知られた。"},
{"title":"交通・貨幣と三都","text":"江戸の日本橋を起点とする[[五街道]]は幕府の直轄とされ、17世紀半ばから[[道中奉行]]が管理した。関東の関所では「[[入鉄砲に出女]]」がきびしく取り締まられた。宿駅の伝馬役を補うために人馬を徴発された村々を[[助郷]]と呼び、宿駅には大名らが泊まる[[本陣]]が置かれた。水上交通では、京都の豪商[[角倉了以]]が鴨川や富士川を整備し、江戸の商人[[河村瑞賢]]は出羽酒田を起点とする東廻り海運・西廻り海運を整えた。大坂・江戸間では17世紀前半から菱垣廻船が、18世紀前半からは酒を運ぶ[[樽廻船]]が運航し、18世紀末頃から日本海では[[北前船]]が活躍した。貨幣では、金座で[[後藤庄三郎]]のもと小判などの計数貨幣が、銀座で丁銀・豆板銀などの[[秤量貨幣]]がつくられ、寛永期には[[寛永通宝]]が大量に鋳造された。東日本の金遣い、西日本の[[銀遣い]]の違いがあり、諸藩は[[藩札]]も発行した。「天下の台所」と呼ばれた大坂には諸藩の[[蔵屋敷]]が置かれ、年貢米や特産物である[[蔵物]]が蔵元を通じて販売された。江戸の[[十組問屋]]や大坂の[[二十四組問屋]]のような問屋仲間の連合組織もつくられ、三井家の[[越後屋]]は「現金かけねなし」の商法で成功した。"}]
pack={"id":"kinsei5","title":"近世⑤（幕政の安定と経済の発展）","subtitle":"家綱・綱吉・正徳の政治・農業と諸産業・交通・三都","order":3.4,"range":"幕政の安定と経済の発展 ── 文治政治への転換・元禄時代・正徳の政治・農業と諸産業・交通・貨幣と三都","timeline":timeline,"lessons":lessons,"quiz":quiz,"ronjutsu":ronj,"terms":terms,"goro":goro,"figures":figures,"cloze":cloze}
s=open('/home/claude/base61.html',encoding='utf-8').read()
m=re.search(r'const DEFAULT_PACKS = (\[[\s\S]*?\n\]);',s); packs=json.loads(m.group(1))
packs=[p for p in packs if p['id']!='kinsei5']
i=[k for k,p in enumerate(packs) if p['id']=='kinsei4'][0]; packs.insert(i+1,pack)
s=s[:m.start(1)]+json.dumps(packs,ensure_ascii=False,indent=1)+s[m.end(1):]
open('/home/claude/base62b.html','w',encoding='utf-8').write(s)
ans=[]
for c in cloze: ans+=re.findall(r'\[\[([^\]]+)\]\]',c['text'])
pl=''.join(re.sub(r'\[\[[^\]]+\]\]','□',c['text']) for c in cloze)
print('cloze',len(ans),'leak',[a for a in set(ans) if a in pl],'overlap',[(a,b) for a in set(ans) for b in set(ans) if a!=b and a in b])
